INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4322718, 623848, 3102, '<td valign="top">I''m not sure this is in the spirit of the challenge, but it''s definitely a cute shot.</td>', 'I''m not sure this is in the spirit of the challenge, but it''s definitely a cute shot.', '2007-12-19 09:54:03.000000', NULL, 1),
(4322732, 623551, 43774, '<td valign="top">That''s a puddle? Gorgeous!!!! Love how the shining water looks like stars. I am not far into the voting but I believe you''ve hit the nail on the head with this challenge.</td>', 'That''s a puddle? Gorgeous!!!! Love how the shining water looks like stars. I am not far into the voting but I believe you''ve hit the nail on the head with this challenge.', '2007-12-19 10:01:02.000000', NULL, 1),
(4322749, 623544, 43774, '<td valign="top">Wow I love this! Love the geometric shapes, the colours of the leaves and the excellent composition.</td>', 'Wow I love this! Love the geometric shapes, the colours of the leaves and the excellent composition.', '2007-12-19 10:07:01.000000', NULL, 1),
(4322755, 623259, 3102, '<td valign="top">I like the concept a lot (and I have a very similar looking trumpet sitting in a very similar looking case in my own basement!).  Compositionally, I think this would have been better had the lower corner of the case not been cut off.  It feels like there''s too much space at the top of the shot.</td>', 'I like the concept a lot (and I have a very similar looking trumpet sitting in a very similar looking case in my own basement!).  Compositionally, I think this would have been better had the lower corner of the case not been cut off.  It feels like there''s too much space at the top of the shot.', '2007-12-19 10:08:05.000000', NULL, 1),
