(4323891, 623874, 83845, '<td valign="top">love the texture and the colors!</td>', 'love the texture and the colors!', '2007-12-19 16:12:24.000000', NULL, 1),
(4323892, 623598, 83940, '<td valign="top">Nice picture, clever use of a tight crop, Nice textures would work well in the Texture challenge this week.</td>', 'Nice picture, clever use of a tight crop, Nice textures would work well in the Texture challenge this week.', '2007-12-19 16:12:25.000000', NULL, 1),
(4323895, 622793, 83845, '<td valign="top">just about sums up the challenge... great job</td>', 'just about sums up the challenge... great job', '2007-12-19 16:12:55.000000', NULL, 1),
(4323896, 623220, 7467, '<td valign="top">nothing is in sharp focus....</td>', 'nothing is in sharp focus....', '2007-12-19 16:13:27.000000', NULL, 1),
(4323897, 623814, 83845, '<td valign="top">cool b&amp;w and fits the challenge nicely</td>', 'cool b&w and fits the challenge nicely', '2007-12-19 16:13:41.000000', NULL, 1),
(4323898, 623021, 7467, '<td valign="top">colors are nice...snapshot does not work for me...sorry</td>', 'colors are nice...snapshot does not work for me...sorry', '2007-12-19 16:13:53.000000', NULL, 1),
