(4324305, 622433, 43774, '<td valign="top">Very beautiful bird and nice light here.</td>', 'Very beautiful bird and nice light here.', '2007-12-19 18:09:21.000000', NULL, 1),
(4324306, 623587, 60321, '<td valign="top">wonderful pictures. It would have been better for me if the overhead palm leaves were not in the picture. it kind of distracts from the real beauty of the ocean.</td>', 'wonderful pictures. It would have been better for me if the overhead palm leaves were not in the picture. it kind of distracts from the real beauty of the ocean.', '2007-12-19 18:09:22.000000', NULL, 1),
(4324307, 623748, 43774, '<td valign="top">I like the muted colours and the composition</td>', 'I like the muted colours and the composition', '2007-12-19 18:09:35.000000', NULL, 1),
(4324309, 623464, 52257, '<td valign="top">Would have liked more contrast.</td>', 'Would have liked more contrast.', '2007-12-19 18:10:05.000000', NULL, 1),
(4324310, 622453, 43774, '<td valign="top">Wish the feet were positioned just a tiny bit better so they were all at one level. As it is now the 2 at the bottom right seem out of place.</td>', 'Wish the feet were positioned just a tiny bit better so they were all at one level. As it is now the 2 at the bottom right seem out of place.', '2007-12-19 18:10:18.000000', NULL, 1),
(4324311, 622793, 60321, '<td valign="top">very nice vibrant colors. The bubbles on the side however don''t quite work for me. It might for others though. Maybe a little more of the egg?</td>', 'very nice vibrant colors. The bubbles on the side however don''t quite work for me. It might for others though. Maybe a little more of the egg?', '2007-12-19 18:10:25.000000', NULL, 1),
(4324315, 623650, 59337, '<td valign="top">I would have liked to see a little more color in this photo, best I have seen so far though. 9 from me</td>', 'I would have liked to see a little more color in this photo, best I have seen so far though. 9 from me', '2007-12-19 18:10:44.000000', NULL, 1),
(4324316, 623874, 43774, '<td valign="top">Good diagonal composition, good detail. Did you try this with a bit more saturation and contrast? I bet it would really pop.</td>', 'Good diagonal composition, good detail. Did you try this with a bit more saturation and contrast? I bet it would really pop.', '2007-12-19 18:10:49.000000', NULL, 1),
(4324318, 622610, 43774, '<td valign="top">Wow my windows never look that good. Love the stark whiteness, it looks pure and clean.</td>', 'Wow my windows never look that good. Love the stark whiteness, it looks pure and clean.', '2007-12-19 18:11:21.000000', NULL, 1),
(4324319, 622776, 43774, '<td valign="top">Interesting idea to flip the image. Very nice symmetrical reflections.</td>', 'Interesting idea to flip the image. Very nice symmetrical reflections.', '2007-12-19 18:12:00.000000', NULL, 1),
(4324321, 623798, 60321, '<td valign="top">very nice capture. <br/> <br/>In my opinion for a picture of this nature, having the whole image in focus would enhance it more rather than an out of focus one.</td>', 'very nice capture.  In my opinion for a picture of this nature, having the whole image in focus would enhance it more rather than an out of focus one.', '2007-12-19 18:12:39.000000', NULL, 1),
(4324322, 623739, 60321, '<td valign="top">I love how the drops of water looks like streams of crystal. quite purrty.</td>', 'I love how the drops of water looks like streams of crystal. quite purrty.', '2007-12-19 18:13:44.000000', NULL, 1),
(4324323, 622782, 60321, '<td valign="top">very abstract and quite artistic.</td>', 'very abstract and quite artistic.', '2007-12-19 18:14:25.000000', NULL, 1),
(4324324, 623645, 59337, '<td valign="top">I don''t know what to say for this one, so I will leave it at that.</td>', 'I don''t know what to say for this one, so I will leave it at that.', '2007-12-19 18:14:47.000000', NULL, 1),
(4324325, 623293, 60321, '<td valign="top">sorry, not quite sure I see the beauty in this picture. Maybe i am missing something</td>', 'sorry, not quite sure I see the beauty in this picture. Maybe i am missing something', '2007-12-19 18:15:10.000000', NULL, 1),
(4324327, 623282, 60321, '<td valign="top">I''m sorry. I''m lost. What is the effect your going for here?</td>', 'I''m sorry. I''m lost. What is the effect your going for here?', '2007-12-19 18:15:52.000000', NULL, 1),
(4324329, 623349, 60321, '<td valign="top">quite majestic</td>', 'quite majestic', '2007-12-19 18:16:28.000000', NULL, 1),
(4324330, 622987, 59337, '<td valign="top">I''m not sure what the goal was here.  I would watch the exposure control and use a faster shutter speed.</td>', 'I''m not sure what the goal was here.  I would watch the exposure control and use a faster shutter speed.', '2007-12-19 18:16:41.000000', NULL, 1),
(4324331, 623192, 60321, '<td valign="top">I like your title, but the picture conveys a lovely sense of peace and contentment.</td>', 'I like your title, but the picture conveys a lovely sense of peace and contentment.', '2007-12-19 18:17:36.000000', NULL, 1),
(4324332, 623551, 60321, '<td valign="top">This is a very beautiful picture! nicely captures and composed.</td>', 'This is a very beautiful picture! nicely captures and composed.', '2007-12-19 18:18:00.000000', NULL, 1),
(4324335, 623256, 60321, '<td valign="top">I would love to wake up to this view every day</td>', 'I would love to wake up to this view every day', '2007-12-19 18:18:17.000000', NULL, 1),
(4324338, 623355, 60321, '<td valign="top">Beautiful picture but i dont think i see how this relates to the challenge.</td>', 'Beautiful picture but i dont think i see how this relates to the challenge.', '2007-12-19 18:18:52.000000', NULL, 1),
(4324340, 623844, 59337, '<td valign="top">It would have been nice to see the subject filling the frame more.</td>', 'It would have been nice to see the subject filling the frame more.', '2007-12-19 18:19:09.000000', NULL, 1),
(4324342, 623703, 60321, '<td valign="top">The picture seems to be a little busy with odd bits and pieces in focus. Would have been better if there for a single point of focus, at least for me.</td>', 'The picture seems to be a little busy with odd bits and pieces in focus. Would have been better if there for a single point of focus, at least for me.', '2007-12-19 18:20:06.000000', NULL, 1),
(4324344, 623375, 60321, '<td valign="top">lovely caption and a beautiful capture.</td>', 'lovely caption and a beautiful capture.', '2007-12-19 18:20:26.000000', NULL, 1),
(4324346, 623870, 59337, '<td valign="top">This feels more like a snap shot then anything else.</td>', 'This feels more like a snap shot then anything else.', '2007-12-19 18:20:46.000000', NULL, 1),
(4324355, 623621, 59337, '<td valign="top">This seems more like a snap shot.</td>', 'This seems more like a snap shot.', '2007-12-19 18:22:27.000000', NULL, 1),
(4324356, 623552, 83328, '<td valign="top">great idea!</td>', 'great idea!', '2007-12-19 18:23:09.000000', NULL, 1),
(4324360, 623282, 59337, '<td valign="top">The forground is distracting.</td>', 'The forground is distracting.', '2007-12-19 18:24:14.000000', NULL, 1),
(4324361, 622567, 60321, '<td valign="top">This picture is really beautiful in its complete abstraction from civilization.</td>', 'This picture is really beautiful in its complete abstraction from civilization.', '2007-12-19 18:24:24.000000', NULL, 1),
(4324362, 623329, 60321, '<td valign="top">lovely composition. I love how the colors combine to portray lovely earthly feel to the picture</td>', 'lovely composition. I love how the colors combine to portray lovely earthly feel to the picture', '2007-12-19 18:25:09.000000', NULL, 1),
(4324363, 623705, 60321, '<td valign="top">very nice picture, nice vibrant colors.</td>', 'very nice picture, nice vibrant colors.', '2007-12-19 18:26:27.000000', NULL, 1),
(4324364, 623742, 83328, '<td valign="top">the road seems to have a litle bit of a color cast</td>', 'the road seems to have a litle bit of a color cast', '2007-12-19 18:26:29.000000', NULL, 1),
(4324365, 622323, 83328, '<td valign="top">really like the tilt!</td>', 'really like the tilt!', '2007-12-19 18:27:06.000000', NULL, 1),
(4324367, 622951, 59337, '<td valign="top">Feels like a snap shot.</td>', 'Feels like a snap shot.', '2007-12-19 18:28:42.000000', NULL, 1),
(4324369, 622625, 83328, '<td valign="top">very creative, liek it a lot.</td>', 'very creative, liek it a lot.', '2007-12-19 18:30:15.000000', NULL, 1),
(4324372, 623544, 83328, '<td valign="top">wow, this is great, i love the colors and composition, although it seems like it could use a little more contrast</td>', 'wow, this is great, i love the colors and composition, although it seems like it could use a little more contrast', '2007-12-19 18:31:51.000000', NULL, 1),
(4324385, 623432, 85886, '<td valign="top">A beautiful picture but unfortunately is just too much of a stretch for even this highly interpretable challenge.  Great shot though :)</td>', 'A beautiful picture but unfortunately is just too much of a stretch for even this highly interpretable challenge.  Great shot though :)', '2007-12-19 18:37:24.000000', NULL, 1),
(4324398, 622705, 85886, '<td valign="top">Another great photo but I have a hard time with the relevance to the challenge.</td>', 'Another great photo but I have a hard time with the relevance to the challenge.', '2007-12-19 18:42:34.000000', NULL, 1),
(4324406, 623870, 85886, '<td valign="top">Doves?  Those look like pigeons to me! :)</td>', 'Doves?  Those look like pigeons to me! :)', '2007-12-19 18:45:27.000000', NULL, 1),
(4324412, 623516, 85886, '<td valign="top">Fantastic shot.  Obviously lovely textures and lighting, and unlike so many in this challenge a directly relevant photo!!  Well done :)</td>', 'Fantastic shot.  Obviously lovely textures and lighting, and unlike so many in this challenge a directly relevant photo!!  Well done :)', '2007-12-19 18:47:07.000000', NULL, 1),
(4324421, 623337, 85886, '<td valign="top">I love the composition and interpretation but it just looks over processed to me, even with basic editing.  Still a very strong shot and this should grab a ribbon (it would if it was my say so!!).  Nice one!</td>', 'I love the composition and interpretation but it just looks over processed to me, even with basic editing.  Still a very strong shot and this should grab a ribbon (it would if it was my say so!!).  Nice one!', '2007-12-19 18:49:22.000000', NULL, 1),
(4324432, 623806, 85886, '<td valign="top">Interesting shot - did you pull the zoom or use a lensbaby (or something else perhaps?)</td>', 'Interesting shot - did you pull the zoom or use a lensbaby (or something else perhaps?)', '2007-12-19 18:53:42.000000', NULL, 1),
(4324490, 623251, 29011, '<td valign="top">My favorite drop shot from the challenge. So clear and warm. The dried out leaves make it very wabi-sabi. I wonder what the warm background is of.</td>', 'My favorite drop shot from the challenge. So clear and warm. The dried out leaves make it very wabi-sabi. I wonder what the warm background is of.', '2007-12-19 19:40:42.000000', NULL, 1),
(4324492, 623616, 86374, '<td valign="top">Beautiful Kitten =)</td>', 'Beautiful Kitten =)', '2007-12-19 19:41:53.000000', NULL, 1),
(4324493, 622625, 29011, '<td valign="top">If people go nitpicking thumbnails they''ll surely miss this fine gem. I didn''t know what to expect when I open this, and was very pleasantly surprised. Has a very Chem Madoz style to it, which I like a lot.</td>', 'If people go nitpicking thumbnails they''ll surely miss this fine gem. I didn''t know what to expect when I open this, and was very pleasantly surprised. Has a very Chem Madoz style to it, which I like a lot.', '2007-12-19 19:42:09.000000', NULL, 1),
(4324495, 622200, 84907, '<td valign="top">Nice clean shot.  I like the symmetry.  I like the choice of greyscale type look as well.  I think having liquid in the two cups or bowl and cup make  those portions of the picture a bit noisier.  I really like that you kept the items in the sink unorganized.  Sometimes less is more and this is just enough things to draw attention but not too many to make me lose focus on the overall image.  Nice job!  I really like the concept.</td>', 'Nice clean shot.  I like the symmetry.  I like the choice of greyscale type look as well.  I think having liquid in the two cups or bowl and cup make  those portions of the picture a bit noisier.  I really like that you kept the items in the sink unorganized.  Sometimes less is more and this is just enough things to draw attention but not too many to make me lose focus on the overall image.  Nice job!  I really like the concept.', '2007-12-19 19:42:34.000000', NULL, 1),
(4324496, 622612, 86374, '<td valign="top">This is extremely interesting to look at.  Especially if you view it as a flat image.  very nice.</td>', 'This is extremely interesting to look at.  Especially if you view it as a flat image.  very nice.', '2007-12-19 19:42:37.000000', NULL, 1),
(4324497, 623870, 86374, '<td valign="top">I acctually find it sad.</td>', 'I acctually find it sad.', '2007-12-19 19:42:56.000000', NULL, 1),
(4324498, 623152, 86374, '<td valign="top">Ya, I totally get this right now.  Awesome capture.</td>', 'Ya, I totally get this right now.  Awesome capture.', '2007-12-19 19:43:26.000000', NULL, 1),
(4324499, 622938, 29011, '<td valign="top">Beautiful capture. Positive tension between the bird and the leaf. It indeed does look like a scene from a story. Great job with the chosen DOF, with the front and back bokeh, and processing.</td>', 'Beautiful capture. Positive tension between the bird and the leaf. It indeed does look like a scene from a story. Great job with the chosen DOF, with the front and back bokeh, and processing.', '2007-12-19 19:43:44.000000', NULL, 1),
(4324500, 622918, 86374, '<td valign="top">Gorgeous.</td>', 'Gorgeous.', '2007-12-19 19:43:58.000000', NULL, 1),
(4324501, 622797, 86374, '<td valign="top">Such a cute little homestead!</td>', 'Such a cute little homestead!', '2007-12-19 19:44:14.000000', NULL, 1),
(4324502, 622149, 29011, '<td valign="top">Nice to see a take on the ole egg. I had an egg shot in mind to but didn''t enter it. Your version fits the challenge better. Nicely done and interesting border.</td>', 'Nice to see a take on the ole egg. I had an egg shot in mind to but didn''t enter it. Your version fits the challenge better. Nicely done and interesting border.', '2007-12-19 19:45:03.000000', NULL, 1),
(4324504, 623241, 84907, '<td valign="top">The contrast from the reddish on the chain to the rock and transition to the snow is wonderful.  I see the beauty in such a simple object.  The layout of the shot is good.  IMHO it probably would have been good to get all of the right side of the rock in the frame.  There could be a thousand reasons why you didn''t so I certainly am not casting stones, but the crop just hits me in a strange place.  Still a very nice shot and how you placed the chain is just excellent!  Very nice job.</td>', 'The contrast from the reddish on the chain to the rock and transition to the snow is wonderful.  I see the beauty in such a simple object.  The layout of the shot is good.  IMHO it probably would have been good to get all of the right side of the rock in the frame.  There could be a thousand reasons why you didn''t so I certainly am not casting stones, but the crop just hits me in a strange place.  Still a very nice shot and how you placed the chain is just excellent!  Very nice job.', '2007-12-19 19:46:11.000000', NULL, 1),
(4324510, 623032, 84907, '<td valign="top">I like the concept and also the choice to move the object from the center of the frame.  Also the choice of white background is a really nice touch.  I think the lack of color in your 1 will probably end up hurting the shot a little, but hey you have to work with the everyday when finding the beauty in the everyday.  A nice shot and I like the thought process.</td>', 'I like the concept and also the choice to move the object from the center of the frame.  Also the choice of white background is a really nice touch.  I think the lack of color in your 1 will probably end up hurting the shot a little, but hey you have to work with the everyday when finding the beauty in the everyday.  A nice shot and I like the thought process.', '2007-12-19 19:48:16.000000', NULL, 1),
(4324517, 623821, 84907, '<td valign="top">A fun and cute picture.  I also like the arrangement of the little snow folks as well.  Not really sure what the green thing is that is hanging into the middle right frame.  It catches my eye and takes me away from little Leah.  But a very nice shot that I am sure your family will love for many years to come.</td>', 'A fun and cute picture.  I also like the arrangement of the little snow folks as well.  Not really sure what the green thing is that is hanging into the middle right frame.  It catches my eye and takes me away from little Leah.  But a very nice shot that I am sure your family will love for many years to come.', '2007-12-19 19:53:05.000000', NULL, 1),
(4324523, 623587, 84907, '<td valign="top">Lots of places for my eye to go here.  The leaning hut is really really distracting to my eye.  The overhanging palm is also distracting to me as well.  I think if you want an overhanging palm I would put more of it in the frame so the viewer knows it is an important part of the image not just a palm that got in the way of a snapshot.  Same thing with the shadows from the palm in front of the camera.  Either more so its deliberate or none at all.</td>', 'Lots of places for my eye to go here.  The leaning hut is really really distracting to my eye.  The overhanging palm is also distracting to me as well.  I think if you want an overhanging palm I would put more of it in the frame so the viewer knows it is an important part of the image not just a palm that got in the way of a snapshot.  Same thing with the shadows from the palm in front of the camera.  Either more so its deliberate or none at all.', '2007-12-19 19:55:46.000000', NULL, 1),
(4324531, 623816, 84907, '<td valign="top">I really like the way you have composed this shot.  The lines have formed a really nice effect to my eye.  We often try so hard to get rid of power lines from our shots it is a great take on this challenge to feature them prominently as everyday beauty.  The background sky is wonderful and provides the shadow as  subject that really makes this shot work for me.  The only thing I have as far as critique is the dark spot in the bottom right.  It does attract my eye pretty quickly, but it is a minor concern.  Great shot.  Not sure how well it will do in the scoring, but I really see it and hope others do as well.</td>', 'I really like the way you have composed this shot.  The lines have formed a really nice effect to my eye.  We often try so hard to get rid of power lines from our shots it is a great take on this challenge to feature them prominently as everyday beauty.  The background sky is wonderful and provides the shadow as  subject that really makes this shot work for me.  The only thing I have as far as critique is the dark spot in the bottom right.  It does attract my eye pretty quickly, but it is a minor concern.  Great shot.  Not sure how well it will do in the scoring, but I really see it and hope others do as well.', '2007-12-19 19:59:55.000000', NULL, 1),
(4324533, 622739, 84907, '<td valign="top">I love the reflection.  Just fantastic.  The sky is also just a really really nice capture.  I am not a huge fan of sun flare, but that isn''t going to dramatically impact my score for the image.  Very nice capture.</td>', 'I love the reflection.  Just fantastic.  The sky is also just a really really nice capture.  I am not a huge fan of sun flare, but that isn''t going to dramatically impact my score for the image.  Very nice capture.', '2007-12-19 20:01:32.000000', NULL, 1),
(4324537, 622165, 84907, '<td valign="top">Gorgeous, I really like this one.  This to me is exactly the thought of the challenge.  I really like the way you framed this shot.  Perfect amount of foreground pine to offset the gorgeous sky behind.  Just a very nice capture of a wonderfully dynamic sky.</td>', 'Gorgeous, I really like this one.  This to me is exactly the thought of the challenge.  I really like the way you framed this shot.  Perfect amount of foreground pine to offset the gorgeous sky behind.  Just a very nice capture of a wonderfully dynamic sky.', '2007-12-19 20:03:08.000000', NULL, 1),
(4324545, 623828, 84907, '<td valign="top">This was the exact same idea I had for this challenge.  I actually took the shot but didn''t enter it because I entered Long Exposure instead.  Doors are far too often overlooked.  I think you did a very nice job with this shot.  The framing and symmetry are wonderful.  I like the colors and how they work with each other as well.  Just a very nice job.  I guess we should both be glad there aren''t two door entries in the same challenge.  :)</td>', 'This was the exact same idea I had for this challenge.  I actually took the shot but didn''t enter it because I entered Long Exposure instead.  Doors are far too often overlooked.  I think you did a very nice job with this shot.  The framing and symmetry are wonderful.  I like the colors and how they work with each other as well.  Just a very nice job.  I guess we should both be glad there aren''t two door entries in the same challenge.  :)', '2007-12-19 20:06:04.000000', NULL, 1),
(4324548, 623190, 84907, '<td valign="top">Wow your house has professional lighting everyday??  :)  I like the shot.  The use of silhouette as form is a very interesting take on the challenge and I think you really pulled of the result.</td>', 'Wow your house has professional lighting everyday??  :)  I like the shot.  The use of silhouette as form is a very interesting take on the challenge and I think you really pulled of the result.', '2007-12-19 20:07:39.000000', NULL, 1),
(4324551, 623660, 84907, '<td valign="top">I like the shot.  The rope leads the viewer through the image and the framing works well for the shot.  The animal tracks could be a positive to animal lovers or a negative to big time purists.  I think it is a very nice solid shot and I think you did a great job.</td>', 'I like the shot.  The rope leads the viewer through the image and the framing works well for the shot.  The animal tracks could be a positive to animal lovers or a negative to big time purists.  I think it is a very nice solid shot and I think you did a great job.', '2007-12-19 20:10:06.000000', NULL, 1),
(4324555, 621944, 84907, '<td valign="top">I think it is a very interesting take on the challenge.  I am surprised to find that I have an issue with the look of this shot.  While it is visually appealing, I do have a problem with the infrared look on a challenge for the everyday.  This isn''t how we see this or any other bench any day let alone every day.  Ok, said that part now I want to talk about the shot because my opinion on that matters little to you, you probably would rather hear what I think of the technicals on the shot.  The primary focus of the bench and the flowing/weeping tree in the foreground is excellent.  The trees in the background to the right are almost completely blown out in my opinion and grab they eye.  The only other critique would probably be some noise issues in the sky.</td>', 'I think it is a very interesting take on the challenge.  I am surprised to find that I have an issue with the look of this shot.  While it is visually appealing, I do have a problem with the infrared look on a challenge for the everyday.  This isn''t how we see this or any other bench any day let alone every day.  Ok, said that part now I want to talk about the shot because my opinion on that matters little to you, you probably would rather hear what I think of the technicals on the shot.  The primary focus of the bench and the flowing/weeping tree in the foreground is excellent.  The trees in the background to the right are almost completely blown out in my opinion and grab they eye.  The only other critique would probably be some noise issues in the sky.', '2007-12-19 20:14:48.000000', NULL, 1),
(4324568, 622938, 60321, '<td valign="top">Very nice use of subtle colors to highlight the beauty of this picture. I love how the birds eyes stand out.</td>', 'Very nice use of subtle colors to highlight the beauty of this picture. I love how the birds eyes stand out.', '2007-12-19 20:24:28.000000', NULL, 1),
(4324570, 622433, 60321, '<td valign="top">Beautiful capture. Very nice bright colors.<br/> <br/>8</td>', 'Beautiful capture. Very nice bright colors. 8', '2007-12-19 20:24:58.000000', NULL, 1),
(4324575, 623880, 60321, '<td valign="top">very nice. I love the shadows and how it enhances the overall beauty of the flower, even though its in its final stages of life.</td>', 'very nice. I love the shadows and how it enhances the overall beauty of the flower, even though its in its final stages of life.', '2007-12-19 20:26:33.000000', NULL, 1),
(4324577, 622910, 84907, '<td valign="top">seeing this much of it I really now want to see the rest of the guitar  :)  I think the colors really serve you well on this one.  I like the use of foreground vs. background.  Just a nice shot.</td>', 'seeing this much of it I really now want to see the rest of the guitar  :)  I think the colors really serve you well on this one.  I like the use of foreground vs. background.  Just a nice shot.', '2007-12-19 20:27:01.000000', NULL, 1),
(4324601, 622099, 60321, '<td valign="top">very nice.</td>', 'very nice.', '2007-12-19 20:37:13.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4324606, 622610, 23484, '<td valign="top">Cool shot.  I really like the lighting.</td>', 'Cool shot.  I really like the lighting.', '2007-12-19 20:38:55.000000', NULL, 1),
(4324613, 623355, 74979, '<td valign="top">love the simplicity &amp; the irony of this image, the old decaying lock and the new vine leaf; tho to hit the true Wabi0Sabi definition, i think focusing on the lock &amp; door alone would have nailed it..6</td>', 'love the simplicity & the irony of this image, the old decaying lock and the new vine leaf; tho to hit the true Wabi0Sabi definition, i think focusing on the lock & door alone would have nailed it..6', '2007-12-19 20:47:31.000000', NULL, 1),
(4324621, 621954, 74979, '<td valign="top">i don''t see decay here, just ripped gloves....nice sharp image &amp; I love the bursts of color as a "beauty in the everyday" finding, too bad we can''t hear his song.</td>', 'i don''t see decay here, just ripped gloves....nice sharp image & I love the bursts of color as a "beauty in the everyday" finding, too bad we can''t hear his song.', '2007-12-19 20:49:53.000000', NULL, 1),
