(4325748, 623461, 23484, '<td valign="top">Very nice capture. I hope you don''t get hit for the soft focus as it really adds to the effect of the shot.</td>', 'Very nice capture. I hope you don''t get hit for the soft focus as it really adds to the effect of the shot.', '2007-12-20 10:48:29.000000', NULL, 1),
(4325749, 623744, 87981, '<td valign="top">I like snow shots</td>', 'I like snow shots', '2007-12-20 10:48:49.000000', NULL, 1),
