(4325751, 622705, 87981, '<td valign="top">Yes, it is cool</td>', 'Yes, it is cool', '2007-12-20 10:50:00.000000', NULL, 1),
(4325753, 622781, 87981, '<td valign="top">Hmmmm</td>', 'Hmmmm', '2007-12-20 10:50:25.000000', NULL, 1),
(4325754, 623739, 23484, '<td valign="top">That is a unique idea. I like the angle.</td>', 'That is a unique idea. I like the angle.', '2007-12-20 10:51:12.000000', NULL, 1),
(4325755, 623355, 87981, '<td valign="top">Excellent</td>', 'Excellent', '2007-12-20 10:51:25.000000', NULL, 1),
(4325756, 623451, 23484, '<td valign="top">Great shot. I really like the color tone.</td>', 'Great shot. I really like the color tone.', '2007-12-20 10:51:38.000000', NULL, 1),
(4325764, 623337, 61679, '<td valign="top">Love the patterns and contrast in this image.  If this was my image I would have cropped out the locked box at the top.  It competes with the meters for my attention. 6</td>', 'Love the patterns and contrast in this image.  If this was my image I would have cropped out the locked box at the top.  It competes with the meters for my attention. 6', '2007-12-20 10:56:13.000000', NULL, 1),
(4325778, 623880, 61679, '<td valign="top">I think you found a wonderful subject for this challenge.  However, the lighting needs to be a bit more dramatic (maybe a bit more from the side) and the image could use more contrast for my taste.  This could be a result of your conversion method to B&amp;W (desat only).  If so, take a look in the tutorial section.  There is a great tutorial on B&amp;W conversion.</td>', 'I think you found a wonderful subject for this challenge.  However, the lighting needs to be a bit more dramatic (maybe a bit more from the side) and the image could use more contrast for my taste.  This could be a result of your conversion method to B&W (desat only).  If so, take a look in the tutorial section.  There is a great tutorial on B&W conversion.', '2007-12-20 10:59:31.000000', NULL, 1),
(4325779, 622358, 68956, '<td valign="top">I like the perspective here, the low view point and the tilt. The burnt out highlights are acceptable - that''s what wet roads do, they glare at you. Fits the challenge well.</td>', 'I like the perspective here, the low view point and the tilt. The burnt out highlights are acceptable - that''s what wet roads do, they glare at you. Fits the challenge well.', '2007-12-20 10:59:53.000000', NULL, 1),
(4325792, 623338, 68956, '<td valign="top">You''ve spotted something good here and the lighting and focus are good too. I think it would be worth playing around with the composition too - shifting the window to the lower left maybe :)</td>', 'You''ve spotted something good here and the lighting and focus are good too. I think it would be worth playing around with the composition too - shifting the window to the lower left maybe :)', '2007-12-20 11:04:26.000000', NULL, 1),
(4325794, 623874, 68956, '<td valign="top">Lovely colours and texture :)</td>', 'Lovely colours and texture :)', '2007-12-20 11:05:30.000000', NULL, 1),
(4325811, 623869, 7467, '<td valign="top">Not sure I see the "beauty"</td>', 'Not sure I see the "beauty"', '2007-12-20 11:10:59.000000', NULL, 1),
(4325812, 623349, 7467, '<td valign="top">It a tough shot to get, but needs to be sharper to "pop"</td>', 'It a tough shot to get, but needs to be sharper to "pop"', '2007-12-20 11:11:34.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4325816, 623744, 7467, '<td valign="top">This looks like a church in South Haven...love the snow (at least in the pic...)</td>', 'This looks like a church in South Haven...love the snow (at least in the pic...)', '2007-12-20 11:12:51.000000', NULL, 1),
(4325818, 622407, 7467, '<td valign="top">Nice fire shot...coals are sharp and the flame colors are great.</td>', 'Nice fire shot...coals are sharp and the flame colors are great.', '2007-12-20 11:13:47.000000', NULL, 1),
(4325821, 623032, 7467, '<td valign="top">would be more dramatic if the subject was brighter...</td>', 'would be more dramatic if the subject was brighter...', '2007-12-20 11:14:19.000000', NULL, 1),
(4325825, 623812, 7467, '<td valign="top">sharper foreground would be more dramatic</td>', 'sharper foreground would be more dramatic', '2007-12-20 11:15:34.000000', NULL, 1),
(4325828, 622987, 68956, '<td valign="top">I''ve looked at this image for a long time trying to work out if I like it or not. The duck on the right keeps catching my eye, is he the spectator? Or am I? There''s a lovely sense of busyness and movement to the image, but in the end the burnt out (white) areas hurt it too much. Thanks for producing an image that made me stop and think :)</td>', 'I''ve looked at this image for a long time trying to work out if I like it or not. The duck on the right keeps catching my eye, is he the spectator? Or am I? There''s a lovely sense of busyness and movement to the image, but in the end the burnt out (white) areas hurt it too much. Thanks for producing an image that made me stop and think :)', '2007-12-20 11:16:18.000000', NULL, 1),
(4325829, 622610, 7467, '<td valign="top">Not working for me...sorry</td>', 'Not working for me...sorry', '2007-12-20 11:16:20.000000', NULL, 1),
(4325831, 622171, 7467, '<td valign="top">beauty????</td>', 'beauty????', '2007-12-20 11:16:36.000000', NULL, 1),
(4325833, 622776, 7467, '<td valign="top">OK...how''d ya do that...</td>', 'OK...how''d ya do that...', '2007-12-20 11:17:37.000000', NULL, 1),
(4325835, 623826, 7467, '<td valign="top">subject is OOF...</td>', 'subject is OOF...', '2007-12-20 11:18:13.000000', NULL, 1),
(4325837, 622239, 7467, '<td valign="top">nothing appears to be in focus....</td>', 'nothing appears to be in focus....', '2007-12-20 11:18:36.000000', NULL, 1),
(4325840, 623726, 7467, '<td valign="top">Nice shot</td>', 'Nice shot', '2007-12-20 11:18:46.000000', NULL, 1),
(4325844, 622797, 7467, '<td valign="top">Suggestions...don''t put the building dead center, and try to sharpen up the bricks in the building.</td>', 'Suggestions...don''t put the building dead center, and try to sharpen up the bricks in the building.', '2007-12-20 11:20:09.000000', NULL, 1),
(4325850, 622705, 15711, '<td valign="top">Interesting take on the challenge.  I rather like it.</td>', 'Interesting take on the challenge.  I rather like it.', '2007-12-20 11:20:51.000000', NULL, 1),
(4325852, 623324, 7467, '<td valign="top">nice colors...</td>', 'nice colors...', '2007-12-20 11:21:05.000000', NULL, 1),
(4325853, 623865, 69368, '<td valign="top">nice composition and really nice colors. but I''m not sure, if this is "Wabis-Sabi"</td>', 'nice composition and really nice colors. but I''m not sure, if this is "Wabis-Sabi"', '2007-12-20 11:21:07.000000', NULL, 1),
(4325855, 623851, 7467, '<td valign="top">sharper subect would be more impactfull</td>', 'sharper subect would be more impactfull', '2007-12-20 11:21:30.000000', NULL, 1),
(4325856, 623461, 69368, '<td valign="top">sorry, but here is everthing out of focus</td>', 'sorry, but here is everthing out of focus', '2007-12-20 11:21:39.000000', NULL, 1),
(4325857, 622625, 15711, '<td valign="top">I like the idea of this but it seems a touch too contrived to suit the definition of "wabi sabi," but maybe I''m being too particular.  I think it would work better if it were less centered and there were more negative space to the left or right.</td>', 'I like the idea of this but it seems a touch too contrived to suit the definition of "wabi sabi," but maybe I''m being too particular.  I think it would work better if it were less centered and there were more negative space to the left or right.', '2007-12-20 11:21:39.000000', NULL, 1),
(4325860, 623329, 15711, '<td valign="top">I love the boards. I think if the flower were real it might have more of the "wabi sabi" feel for me.  Not crazy about the text on the bottle.  Nice composition and focus.</td>', 'I love the boards. I think if the flower were real it might have more of the "wabi sabi" feel for me.  Not crazy about the text on the bottle.  Nice composition and focus.', '2007-12-20 11:22:38.000000', NULL, 1),
(4325862, 623544, 15711, '<td valign="top">This does have a certainZzen feel.  I like the mix of the angular and the natural. Maybe a touch busy, but still, the colors and tones are lovely.</td>', 'This does have a certainZzen feel.  I like the mix of the angular and the natural. Maybe a touch busy, but still, the colors and tones are lovely.', '2007-12-20 11:23:40.000000', NULL, 1),
(4325863, 623357, 15711, '<td valign="top">The lighting and DOF make the shot.  It works being centered and that''s not often the case. ;~D</td>', 'The lighting and DOF make the shot.  It works being centered and that''s not often the case. ;~D', '2007-12-20 11:24:00.000000', NULL, 1),
(4325865, 623726, 15711, '<td valign="top">This is lovely.  I am such a fan of a dew ridden spider web. I might''ve cropped it so that the diagonal branch in the lower right isn''t there.  I don''t think it would detract from the overall shape of the web. Like pearls aren''t they?</td>', 'This is lovely.  I am such a fan of a dew ridden spider web. I might''ve cropped it so that the diagonal branch in the lower right isn''t there.  I don''t think it would detract from the overall shape of the web. Like pearls aren''t they?', '2007-12-20 11:25:00.000000', NULL, 1),
(4325867, 623748, 15711, '<td valign="top">This certainly suits the definition but I think to have that Zen quality of wabi sabi, it''s a touch busy.  I''d have removed the plant and pot, the rug, and just had the bottle with the brick background. If those items were missing, the eye would go immediately to the bottle and not be confused by several other objects. I love old bottles. ;~D</td>', 'This certainly suits the definition but I think to have that Zen quality of wabi sabi, it''s a touch busy.  I''d have removed the plant and pot, the rug, and just had the bottle with the brick background. If those items were missing, the eye would go immediately to the bottle and not be confused by several other objects. I love old bottles. ;~D', '2007-12-20 11:26:45.000000', NULL, 1),
(4325878, 623211, 61679, '<td valign="top">Back to comment: Been there, done that, love it. 9</td>', 'Back to comment: Been there, done that, love it. 9', '2007-12-20 11:43:14.000000', NULL, 1),
(4325879, 622776, 71526, '<td valign="top">Nice reflection.</td>', 'Nice reflection.', '2007-12-20 11:43:19.000000', NULL, 1),
(4325883, 623726, 66932, '<td valign="top">Lovely picture.  Even the web isn''t perfect, yet the whole makes a wonderful image.  Captures the idea behind the challenge to perfection.</td>', 'Lovely picture.  Even the web isn''t perfect, yet the whole makes a wonderful image.  Captures the idea behind the challenge to perfection.', '2007-12-20 11:44:50.000000', NULL, 1),
(4325895, 622776, 66932, '<td valign="top">You were very fortunate with the light to get such a beautiful image.  And I agree it looks better this way up!</td>', 'You were very fortunate with the light to get such a beautiful image.  And I agree it looks better this way up!', '2007-12-20 11:48:11.000000', NULL, 1),
(4325900, 623575, 66932, '<td valign="top">I like this one a lot.  The beauty is in the colour of the background and the texture of the foreground.</td>', 'I like this one a lot.  The beauty is in the colour of the background and the texture of the foreground.', '2007-12-20 11:50:59.000000', NULL, 1),
(4325902, 622793, 66932, '<td valign="top">This is wonderfully well chosen for the challenge.  Colours are stunning and the everyday nature of the subject is obvious.</td>', 'This is wonderfully well chosen for the challenge.  Colours are stunning and the everyday nature of the subject is obvious.', '2007-12-20 11:52:40.000000', NULL, 1),
(4325906, 623826, 66932, '<td valign="top">Very well chosen.  Most people would never even notice!  Excellent.</td>', 'Very well chosen.  Most people would never even notice!  Excellent.', '2007-12-20 11:54:12.000000', NULL, 1),
(4325907, 622918, 61679, '<td valign="top">Back to comment: The tension created by having the chair face the outside of the image is wonderful.  I would have like to see a bit more white to the snow.  Nice job. 8</td>', 'Back to comment: The tension created by having the chair face the outside of the image is wonderful.  I would have like to see a bit more white to the snow.  Nice job. 8', '2007-12-20 11:54:29.000000', NULL, 1),
(4325909, 623877, 66932, '<td valign="top">Hardly everyday.  Nice shot though.</td>', 'Hardly everyday.  Nice shot though.', '2007-12-20 11:55:46.000000', NULL, 1),
(4325910, 623552, 61679, '<td valign="top">Back to comment:  A very creative idea and nicely done.  If you could have changed the lighting just a bit to provide some detail in the flower pedals, it would have been exceptional. 7</td>', 'Back to comment:  A very creative idea and nicely done.  If you could have changed the lighting just a bit to provide some detail in the flower pedals, it would have been exceptional. 7', '2007-12-20 11:57:27.000000', NULL, 1),
(4325912, 622790, 61679, '<td valign="top">Back to comment and bump.  Nice capture with an ageless feel. 8</td>', 'Back to comment and bump.  Nice capture with an ageless feel. 8', '2007-12-20 11:58:17.000000', NULL, 1),
(4325913, 622494, 74979, '<td valign="top">lovely clear image and nice interpretation of WabiSabi in the burrs<br/> <br/>(or is it brrrr? :)</td>', 'lovely clear image and nice interpretation of WabiSabi in the burrs (or is it brrrr? :)', '2007-12-20 11:58:17.000000', NULL, 1),
(4325918, 623819, 66932, '<td valign="top">Lovely atmosphere to this one.</td>', 'Lovely atmosphere to this one.', '2007-12-20 12:02:49.000000', NULL, 1),
(4325923, 623375, 66932, '<td valign="top">Not enough depth of focus for me - the nose bothers me.  But otherwise I like it a lot.</td>', 'Not enough depth of focus for me - the nose bothers me.  But otherwise I like it a lot.', '2007-12-20 12:04:19.000000', NULL, 1),
(4325926, 623227, 66932, '<td valign="top">Well captures the idea of the challenge.  Very nice.</td>', 'Well captures the idea of the challenge.  Very nice.', '2007-12-20 12:06:05.000000', NULL, 1),
(4325929, 623739, 66932, '<td valign="top">Very good!</td>', 'Very good!', '2007-12-20 12:09:36.000000', NULL, 1),
(4325978, 623816, 54778, '<td valign="top">Great composition and colour..</td>', 'Great composition and colour..', '2007-12-20 12:35:28.000000', NULL, 1),
(4326009, 623016, 75192, '<td valign="top">Oh, now this is just beautiful. I''ve similar things done, but nice shot.</td>', 'Oh, now this is just beautiful. I''ve similar things done, but nice shot.', '2007-12-20 12:48:01.000000', NULL, 1),
(4326016, 623645, 87907, '<td valign="top">Sorry...I can''t place a high vote on this.  It looks like a cell phone picture.  It is not really pleasing to the eye. The exposure isn''t good.  And it definitely doesn''t fall into the category ''beauty in the everyday''.</td>', 'Sorry...I can''t place a high vote on this.  It looks like a cell phone picture.  It is not really pleasing to the eye. The exposure isn''t good.  And it definitely doesn''t fall into the category ''beauty in the everyday''.', '2007-12-20 12:50:58.000000', NULL, 1),
(4326036, 623771, 52169, '<td valign="top">I love the cloring and the compostion.</td>', 'I love the cloring and the compostion.', '2007-12-20 12:59:22.000000', NULL, 1),
(4326043, 623496, 52169, '<td valign="top">Finally, This is beautiful. Great image, Great balance, Great in B/W. Thanks for taking this one. 10</td>', 'Finally, This is beautiful. Great image, Great balance, Great in B/W. Thanks for taking this one. 10', '2007-12-20 13:02:00.000000', NULL, 1),
(4326046, 622918, 52169, '<td valign="top">I love the simplicity of the image. I wish it were a little mor high key. But, that is my taste. 8</td>', 'I love the simplicity of the image. I wish it were a little mor high key. But, that is my taste. 8', '2007-12-20 13:03:03.000000', NULL, 1),
(4326068, 623645, 71526, '<td valign="top">errr...... really?</td>', 'errr...... really?', '2007-12-20 13:14:06.000000', NULL, 1),
(4326075, 623819, 23484, '<td valign="top">I like the softness and the colors. Great job.</td>', 'I like the softness and the colors. Great job.', '2007-12-20 13:18:21.000000', NULL, 1),
(4326091, 622793, 61679, '<td valign="top">Back to comment: This wins the most original idea award in my opinion.  Wonderful colors and composition. 10</td>', 'Back to comment: This wins the most original idea award in my opinion.  Wonderful colors and composition. 10', '2007-12-20 13:23:48.000000', NULL, 1),
(4326092, 622200, 61679, '<td valign="top">Back to comment:  The lighting and post processing make this image a true work of art. 10</td>', 'Back to comment:  The lighting and post processing make this image a true work of art. 10', '2007-12-20 13:23:55.000000', NULL, 1),
(4326094, 622694, 71526, '<td valign="top">Perfect focus, perfect shot! Like your title.</td>', 'Perfect focus, perfect shot! Like your title.', '2007-12-20 13:24:04.000000', NULL, 1),
(4326095, 623598, 61679, '<td valign="top">Back to comment: Wonderful contrast and texture.  Exceptional composition.  Nicely done. 10</td>', 'Back to comment: Wonderful contrast and texture.  Exceptional composition.  Nicely done. 10', '2007-12-20 13:24:06.000000', NULL, 1),
(4326097, 623251, 61679, '<td valign="top">Back to comment: Exceptionally strong composition.  Nicely done. 10</td>', 'Back to comment: Exceptionally strong composition.  Nicely done. 10', '2007-12-20 13:24:13.000000', NULL, 1),
(4326127, 623816, 71526, '<td valign="top">I like your concept here! good work.</td>', 'I like your concept here! good work.', '2007-12-20 13:32:21.000000', NULL, 1),
(4326139, 623744, 71526, '<td valign="top">Better without the wires, but yep... basic editing. Nice!</td>', 'Better without the wires, but yep... basic editing. Nice!', '2007-12-20 13:35:15.000000', NULL, 1),
(4326151, 623822, 71526, '<td valign="top">Your high key works great here. Good work!</td>', 'Your high key works great here. Good work!', '2007-12-20 13:37:22.000000', NULL, 1),
(4326162, 623739, 71526, '<td valign="top">Good idea here! Good shot!</td>', 'Good idea here! Good shot!', '2007-12-20 13:41:24.000000', NULL, 1),
(4326169, 623650, 71526, '<td valign="top">Great capture here. Love the high key of your shot.</td>', 'Great capture here. Love the high key of your shot.', '2007-12-20 13:42:50.000000', NULL, 1),
(4326182, 623552, 71526, '<td valign="top">Really really great wabi-sabi concept here. Good work!</td>', 'Really really great wabi-sabi concept here. Good work!', '2007-12-20 13:50:17.000000', NULL, 1),
(4326246, 623819, 66193, '<td valign="top">very ethereal, Catherine.   i do like how the increased saturation works here. nicely composed. no vote, of course.</td>', 'very ethereal, Catherine.   i do like how the increased saturation works here. nicely composed. no vote, of course.', '2007-12-20 14:21:45.000000', NULL, 1),
(4326254, 622610, 66193, '<td valign="top">mesmerizing.  I really like this one.  It seems to glow. bumped +1</td>', 'mesmerizing.  I really like this one.  It seems to glow. bumped +1', '2007-12-20 14:25:04.000000', NULL, 1),
(4326257, 623618, 66193, '<td valign="top">life is transient.  wabi-sabi definitely!  very nice capture.  i like the toning, nicely sharp and interesting composition. bumped +1</td>', 'life is transient.  wabi-sabi definitely!  very nice capture.  i like the toning, nicely sharp and interesting composition. bumped +1', '2007-12-20 14:25:14.000000', NULL, 1),
(4326258, 623818, 66193, '<td valign="top">I like the toning here.</td>', 'I like the toning here.', '2007-12-20 14:25:44.000000', NULL, 1),
(4326259, 622284, 43774, '<td valign="top">Very good exposure, good use of negative space</td>', 'Very good exposure, good use of negative space', '2007-12-20 14:26:04.000000', NULL, 1),
(4326261, 623818, 43774, '<td valign="top">A nice composition, I like the sepia</td>', 'A nice composition, I like the sepia', '2007-12-20 14:26:18.000000', NULL, 1),
(4326263, 623816, 43774, '<td valign="top">I like the silhouettes although it is a bit contrasty, that makes the lines jagged. Not sure if you enhanced the colour of the sky. Not sure if I like it or not.</td>', 'I like the silhouettes although it is a bit contrasty, that makes the lines jagged. Not sure if you enhanced the colour of the sky. Not sure if I like it or not.', '2007-12-20 14:27:07.000000', NULL, 1),
(4326264, 623848, 43774, '<td valign="top">Very sweet. Maybe a bit too bright as the toy blends into the background.</td>', 'Very sweet. Maybe a bit too bright as the toy blends into the background.', '2007-12-20 14:27:35.000000', NULL, 1),
(4326267, 623851, 43774, '<td valign="top">I like the composition. Did you saturate the colours? They seem a bit oversaturated and the blown out whites are a bit distracting. But all in all a fine photo.</td>', 'I like the composition. Did you saturate the colours? They seem a bit oversaturated and the blown out whites are a bit distracting. But all in all a fine photo.', '2007-12-20 14:28:31.000000', NULL, 1),
