(4329194, 621900, 43774, '<td valign="top">Very nice backlighting, nice colours</td>', 'Very nice backlighting, nice colours', '2007-12-21 21:01:02.000000', NULL, 1),
(4329196, 622889, 43774, '<td valign="top">Nice and clear, B&amp;W works well. But I am not so sure about the composition/angle. I''d love to see it looking down on the father and child, not looking up. It seems a bit awkward.</td>', 'Nice and clear, B&W works well. But I am not so sure about the composition/angle. I''d love to see it looking down on the father and child, not looking up. It seems a bit awkward.', '2007-12-21 21:01:56.000000', NULL, 1),
(4329198, 623234, 43774, '<td valign="top">Less centered would make this stronger, in my opinion.</td>', 'Less centered would make this stronger, in my opinion.', '2007-12-21 21:02:21.000000', NULL, 1),
(4329200, 622793, 43774, '<td valign="top">I like the composition and the idea. It seems slightly out of focus and the reflections are distracting.</td>', 'I like the composition and the idea. It seems slightly out of focus and the reflections are distracting.', '2007-12-21 21:03:06.000000', NULL, 1),
(4329201, 622987, 43774, '<td valign="top">Everyday, yes. Beautiful? Well, I guess beauty is in the eye of the beholder. Sorry, I don''t find the overexposed blurry photo beautiful. Hopefully there are people out there who do.</td>', 'Everyday, yes. Beautiful? Well, I guess beauty is in the eye of the beholder. Sorry, I don''t find the overexposed blurry photo beautiful. Hopefully there are people out there who do.', '2007-12-21 21:04:16.000000', NULL, 1),
