(4329919, 622782, 51750, '<td valign="top">This does not look everyday-like to me. Smoke yes, orange strobed light no.</td>', 'This does not look everyday-like to me. Smoke yes, orange strobed light no.', '2007-12-22 13:38:06.000000', NULL, 1),
(4329996, 622705, 66267, '<td valign="top">interesting lighting, maybe the hands are too dark. Lame title</td>', 'interesting lighting, maybe the hands are too dark. Lame title', '2007-12-22 15:01:44.000000', NULL, 1),
(4329997, 622171, 66267, '<td valign="top">focus is a bit soft. Cool subject.</td>', 'focus is a bit soft. Cool subject.', '2007-12-22 15:02:29.000000', NULL, 1),
