(4330005, 622945, 66267, '<td valign="top">no clue what im looking at</td>', 'no clue what im looking at', '2007-12-22 15:09:05.000000', NULL, 1),
(4330006, 623227, 66267, '<td valign="top">intersting perspective</td>', 'intersting perspective', '2007-12-22 15:09:39.000000', NULL, 1),
(4330082, 623283, 55117, '<td valign="top">A bit too blue and the sharpened noise makes the image look very "jagged".</td>', 'A bit too blue and the sharpened noise makes the image look very "jagged".', '2007-12-22 16:50:36.000000', NULL, 1),
(4330083, 622493, 55117, '<td valign="top">Potentially gorgeous shot, but the depth of field is too shallow. Had the far eye been in focus, this would have been very nice.</td>', 'Potentially gorgeous shot, but the depth of field is too shallow. Had the far eye been in focus, this would have been very nice.', '2007-12-22 16:52:02.000000', NULL, 1),
(4330086, 623848, 55117, '<td valign="top">Cute, but not particuarly remarkable. Had those big eyes been staring into the lens, it would have been worth a 7 or 8.</td>', 'Cute, but not particuarly remarkable. Had those big eyes been staring into the lens, it would have been worth a 7 or 8.', '2007-12-22 16:52:57.000000', NULL, 1),
(4330087, 622494, 55117, '<td valign="top">No real purpose for retaining the color in this shot. Brown and white isn''t all that appealing.</td>', 'No real purpose for retaining the color in this shot. Brown and white isn''t all that appealing.', '2007-12-22 16:53:37.000000', NULL, 1),
(4330088, 623433, 55117, '<td valign="top">Like the concept. Not so keen on the execution.</td>', 'Like the concept. Not so keen on the execution.', '2007-12-22 16:54:03.000000', NULL, 1),
(4330089, 623251, 55117, '<td valign="top">Goergous sharp focus and nice bokeh.</td>', 'Goergous sharp focus and nice bokeh.', '2007-12-22 16:54:21.000000', NULL, 1),
(4330091, 622171, 55117, '<td valign="top">Looks like a snapshot made with a cheap point-and-shoot. Boring composition, desaturated colors, blown-out lighting (no doubt the on-camera flash). You can''t simply rely on an interesting subject to compensate for a bad picture. Take more risks with composition...experiment a bit.</td>', 'Looks like a snapshot made with a cheap point-and-shoot. Boring composition, desaturated colors, blown-out lighting (no doubt the on-camera flash). You can''t simply rely on an interesting subject to compensate for a bad picture. Take more risks with composition...experiment a bit.', '2007-12-22 16:56:53.000000', NULL, 1),
(4330092, 623665, 55117, '<td valign="top">Very cool. Normally I detest pretentious simplicity, but this turned out kind of interesting.</td>', 'Very cool. Normally I detest pretentious simplicity, but this turned out kind of interesting.', '2007-12-22 16:57:41.000000', NULL, 1),
(4330094, 623559, 55117, '<td valign="top">...and focus transcends blur...try a smaller aperture.</td>', '...and focus transcends blur...try a smaller aperture.', '2007-12-22 16:58:22.000000', NULL, 1),
(4330096, 623329, 55117, '<td valign="top">Another potentially great shot hindered by poor composition, poor lighting,  and no color saturation. Had the whole bottle been in the shot with some soft lighting on the flower, and a little post-processing to enhance saturation, this would have been killer. Why is it being lit from behind? That just screams "rushed shot". Plan this stuff out if you intend to enter it into competitions.</td>', 'Another potentially great shot hindered by poor composition, poor lighting,  and no color saturation. Had the whole bottle been in the shot with some soft lighting on the flower, and a little post-processing to enhance saturation, this would have been killer. Why is it being lit from behind? That just screams "rushed shot". Plan this stuff out if you intend to enter it into competitions.', '2007-12-22 17:00:58.000000', NULL, 1),
(4330097, 623700, 55117, '<td valign="top">Not particularly interesting.</td>', 'Not particularly interesting.', '2007-12-22 17:01:13.000000', NULL, 1),
(4330098, 623324, 55117, '<td valign="top">A boring top-down shot on a metallic griddle?</td>', 'A boring top-down shot on a metallic griddle?', '2007-12-22 17:01:43.000000', NULL, 1),
(4330099, 622793, 55117, '<td valign="top">Very neat. Nice use of macro.</td>', 'Very neat. Nice use of macro.', '2007-12-22 17:02:04.000000', NULL, 1),
(4330100, 622931, 55117, '<td valign="top">Oh what a little bit of post-processing could achieve here. As-is, it''s dull. WIth a little more contrast and some color correction this would be awesome.</td>', 'Oh what a little bit of post-processing could achieve here. As-is, it''s dull. WIth a little more contrast and some color correction this would be awesome.', '2007-12-22 17:03:00.000000', NULL, 1),
(4330101, 623878, 55117, '<td valign="top">I like the sharpness. Very nice, even if the subject isn''t entirely unique or interesting.</td>', 'I like the sharpness. Very nice, even if the subject isn''t entirely unique or interesting.', '2007-12-22 17:03:20.000000', NULL, 1),
(4330102, 623493, 55117, '<td valign="top">Very cool. Love the lighting.</td>', 'Very cool. Love the lighting.', '2007-12-22 17:03:35.000000', NULL, 1),
(4330103, 623870, 55117, '<td valign="top">Snapshot.</td>', 'Snapshot.', '2007-12-22 17:03:55.000000', NULL, 1),
(4330104, 623383, 55117, '<td valign="top">Nice capture. Needs some contrast.</td>', 'Nice capture. Needs some contrast.', '2007-12-22 17:04:18.000000', NULL, 1),
(4330105, 622566, 55117, '<td valign="top">Blown highlights. Needs the exposure turned down a bit, and more contrast.</td>', 'Blown highlights. Needs the exposure turned down a bit, and more contrast.', '2007-12-22 17:04:50.000000', NULL, 1),
(4330106, 622910, 55117, '<td valign="top">Love the colors. The little bit of chromic aberration in the over-sharp bokeh actually looks fine here.</td>', 'Love the colors. The little bit of chromic aberration in the over-sharp bokeh actually looks fine here.', '2007-12-22 17:05:30.000000', NULL, 1),
(4330107, 623126, 55117, '<td valign="top">Oh lord. Flower shot.</td>', 'Oh lord. Flower shot.', '2007-12-22 17:05:40.000000', NULL, 1),
(4330108, 622323, 55117, '<td valign="top">Lovely capture. Nice use of black and white to make the most of a blown sky. Deserves a 6. Very good.</td>', 'Lovely capture. Nice use of black and white to make the most of a blown sky. Deserves a 6. Very good.', '2007-12-22 17:06:22.000000', NULL, 1),
(4330109, 623867, 55117, '<td valign="top">Love the sharpness.</td>', 'Love the sharpness.', '2007-12-22 17:06:34.000000', NULL, 1),
(4330110, 623513, 55117, '<td valign="top">Not particularly interesting.</td>', 'Not particularly interesting.', '2007-12-22 17:06:49.000000', NULL, 1),
(4330112, 623858, 55117, '<td valign="top">Gorgeous sky and I like the silhouette.</td>', 'Gorgeous sky and I like the silhouette.', '2007-12-22 17:07:14.000000', NULL, 1),
(4330113, 623653, 55117, '<td valign="top">Love the sharp contrast.</td>', 'Love the sharp contrast.', '2007-12-22 17:07:30.000000', NULL, 1),
(4330115, 622782, 55117, '<td valign="top">Ah the old overdone smoke shot. Time to find something new. This is about as creative as flower macros anymore.</td>', 'Ah the old overdone smoke shot. Time to find something new. This is about as creative as flower macros anymore.', '2007-12-22 17:08:41.000000', NULL, 1),
(4330210, 623645, 69045, '<td valign="top">dnmc</td>', 'dnmc', '2007-12-22 17:48:28.000000', NULL, 1),
