INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4330701, 623650, 88054, '<td valign="top">Great message</td>', 'Great message', '2007-12-23 00:28:11.000000', NULL, 1),
(4330707, 623334, 88054, '<td valign="top">Been There. lovely.</td>', 'Been There. lovely.', '2007-12-23 00:32:57.000000', NULL, 1),
(4330709, 623858, 88054, '<td valign="top">Beautiful colors</td>', 'Beautiful colors', '2007-12-23 00:33:18.000000', NULL, 1),
(4330712, 623552, 88054, '<td valign="top">Clever</td>', 'Clever', '2007-12-23 00:34:00.000000', NULL, 1),
(4330717, 623061, 88054, '<td valign="top">Peaceful</td>', 'Peaceful', '2007-12-23 00:36:51.000000', NULL, 1),
(4330749, 622873, 83902, '<td valign="top">I don''t know if you used editing or not, but my first thought was that the white was too white, if that makes any sense to you. but it is a good picture.</td>', 'I don''t know if you used editing or not, but my first thought was that the white was too white, if that makes any sense to you. but it is a good picture.', '2007-12-23 01:18:43.000000', NULL, 1),
(4330886, 623516, 34938, '<td valign="top">nice textures and hues in the light...7</td>', 'nice textures and hues in the light...7', '2007-12-23 07:37:04.000000', NULL, 1),
(4330887, 622790, 34938, '<td valign="top">wow...beautiful image and light...</td>', 'wow...beautiful image and light...', '2007-12-23 07:38:18.000000', NULL, 1),
(4330908, 622743, 12674, '<td valign="top">Very neat, active scene on the hill. I might''ve composed to include less of the foreground benches, as they distract me a bit from the more interesting hillside activity.</td>', 'Very neat, active scene on the hill. I might''ve composed to include less of the foreground benches, as they distract me a bit from the more interesting hillside activity.', '2007-12-23 08:39:21.000000', NULL, 1),
(4330918, 623349, 12674, '<td valign="top">Nice shot - incredible gaze! The sky could be a bit less grainy.  You might try Neat Image, an image smoothing program you can download as a demo for free.</td>', 'Nice shot - incredible gaze! The sky could be a bit less grainy.  You might try Neat Image, an image smoothing program you can download as a demo for free.', '2007-12-23 08:46:25.000000', NULL, 1),
(4330922, 623515, 12674, '<td valign="top">Beautiful color, impressionistic.</td>', 'Beautiful color, impressionistic.', '2007-12-23 08:49:26.000000', NULL, 1),
(4330925, 623828, 12674, '<td valign="top">Nice shot of an impressive door - I wonder where it leads? The cropping is nice. You might try adjusting color balance to add some warmth.</td>', 'Nice shot of an impressive door - I wonder where it leads? The cropping is nice. You might try adjusting color balance to add some warmth.', '2007-12-23 08:57:54.000000', NULL, 1),
(4330973, 622739, 44877, '<td valign="top">Beautiful photo that has a lot of potential. It would benefit from you using the maximum size allowed - 640 on any or all sides.</td>', 'Beautiful photo that has a lot of potential. It would benefit from you using the maximum size allowed - 640 on any or all sides.', '2007-12-23 11:04:27.000000', NULL, 1),
(4330975, 622239, 44877, '<td valign="top">Not so good photo quality. Contrast is lacking, it''s grainy and unfocused. Don''t know if that''s the look you were going for.</td>', 'Not so good photo quality. Contrast is lacking, it''s grainy and unfocused. Don''t know if that''s the look you were going for.', '2007-12-23 11:06:51.000000', NULL, 1),
(4330976, 623668, 84328, '<td valign="top">very cool picture</td>', 'very cool picture', '2007-12-23 11:20:35.000000', NULL, 1),
(4331012, 623826, 83313, '<td valign="top">You caught the light showing off those wet mushrooms just right. I Like it. I might''ve cropped in a little tighter to give the mushrooms more impact and reduce the visual intrusion of the out of focus zones.</td>', 'You caught the light showing off those wet mushrooms just right. I Like it. I might''ve cropped in a little tighter to give the mushrooms more impact and reduce the visual intrusion of the out of focus zones.', '2007-12-23 12:09:30.000000', NULL, 1),
(4331017, 623220, 83313, '<td valign="top">I''m not sure if the mild sepia tone works for this or not. Having the branch against a bolder white background may have worked better. I can certainly appreciate the effort to do something a little different, as there a lot of snow shots right now!</td>', 'I''m not sure if the mild sepia tone works for this or not. Having the branch against a bolder white background may have worked better. I can certainly appreciate the effort to do something a little different, as there a lot of snow shots right now!', '2007-12-23 12:12:53.000000', NULL, 1),
(4331018, 622625, 83313, '<td valign="top">Very creative. It absolutely shows the beauty in everyday things. Fits both "everyday" and "Wabi-Sabi".</td>', 'Very creative. It absolutely shows the beauty in everyday things. Fits both "everyday" and "Wabi-Sabi".', '2007-12-23 12:14:37.000000', NULL, 1),
(4331019, 623806, 44877, '<td valign="top">Acorn on acid. This particular blur is a bit dizzying.</td>', 'Acorn on acid. This particular blur is a bit dizzying.', '2007-12-23 12:15:09.000000', NULL, 1),
(4331021, 622705, 44877, '<td valign="top">Excellent clarity, interesting lighting, fun concept. You got one of two 10s I doled out.</td>', 'Excellent clarity, interesting lighting, fun concept. You got one of two 10s I doled out.', '2007-12-23 12:16:23.000000', NULL, 1),
(4331023, 622380, 44877, '<td valign="top">Totally brilliant and absolutely fitting the challenge.</td>', 'Totally brilliant and absolutely fitting the challenge.', '2007-12-23 12:16:56.000000', NULL, 1),
(4331024, 622099, 83313, '<td valign="top">Reminds me of a Japanese proverb: "The nail that sticks up gets hit by the hammer". It''s the flip side of "The squeaky wheel gets the grease". This is a good shot. Fits both "everyday" and "Wabi-Sabi".</td>', 'Reminds me of a Japanese proverb: "The nail that sticks up gets hit by the hammer". It''s the flip side of "The squeaky wheel gets the grease". This is a good shot. Fits both "everyday" and "Wabi-Sabi".', '2007-12-23 12:17:00.000000', NULL, 1),
(4331029, 622726, 83313, '<td valign="top">Nice detail and tone. It would make a fine illustration to show it in a book or on Ebay. I just don''t find much to hold my interest in the view of it. A little too plain a view of an interesting item.</td>', 'Nice detail and tone. It would make a fine illustration to show it in a book or on Ebay. I just don''t find much to hold my interest in the view of it. A little too plain a view of an interesting item.', '2007-12-23 12:22:08.000000', NULL, 1),
(4331030, 623742, 83313, '<td valign="top">A really cool perspective. Shows an eye that is always looking at the world through a viewfinder.</td>', 'A really cool perspective. Shows an eye that is always looking at the world through a viewfinder.', '2007-12-23 12:23:49.000000', NULL, 1),
(4331031, 623340, 83313, '<td valign="top">It''s a nice loving scene that fits "everyday", though I don''t see it fitting the "Wabi-Sabi" idea. It is well done, however.</td>', 'It''s a nice loving scene that fits "everyday", though I don''t see it fitting the "Wabi-Sabi" idea. It is well done, however.', '2007-12-23 12:25:10.000000', NULL, 1),
(4331032, 623822, 83313, '<td valign="top">More snow! I wonder why there are so many snow shots this week? (Duh!) <br/> <br/>I like the contrasty b/w. The appearance is almost that of a pencil drawing. I don''t see it fitting the "Wabi-Sabi" idea, though it does fit "everyday".</td>', 'More snow! I wonder why there are so many snow shots this week? (Duh!)  I like the contrasty b/w. The appearance is almost that of a pencil drawing. I don''t see it fitting the "Wabi-Sabi" idea, though it does fit "everyday".', '2007-12-23 12:28:36.000000', NULL, 1),
(4331038, 622185, 83313, '<td valign="top">Very cool looking. Brings back memories of frost on my window as a kid. I live in Texas now, where I don''t get to see much of this. But, I don''t get to shovel my driveway, either! Bumping up the colors a touch may have worked, but the more subtle approach is good as well.</td>', 'Very cool looking. Brings back memories of frost on my window as a kid. I live in Texas now, where I don''t get to see much of this. But, I don''t get to shovel my driveway, either! Bumping up the colors a touch may have worked, but the more subtle approach is good as well.', '2007-12-23 12:31:52.000000', NULL, 1),
(4331041, 622165, 83313, '<td valign="top">I really like the contrast of the sepia toned trees against the cloudy sky. I don''t know if the composition is flowing for me, though.</td>', 'I really like the contrast of the sepia toned trees against the cloudy sky. I don''t know if the composition is flowing for me, though.', '2007-12-23 12:33:25.000000', NULL, 1),
(4331051, 623061, 83313, '<td valign="top">Nice and crisp. I think you intentionally centered this. Maybe a tighter crop would have had more wow factor. I like the stark shadows on the snow, though the houses distract a little from the rest of the scene. I''m really divided on this one.</td>', 'Nice and crisp. I think you intentionally centered this. Maybe a tighter crop would have had more wow factor. I like the stark shadows on the snow, though the houses distract a little from the rest of the scene. I''m really divided on this one.', '2007-12-23 12:38:29.000000', NULL, 1),
(4331054, 623355, 83313, '<td valign="top">This is really cool. It absolutely shows the beauty in everyday things. Fits "Wabi-Sabi" to perfection. (Is that an oxymoron?)</td>', 'This is really cool. It absolutely shows the beauty in everyday things. Fits "Wabi-Sabi" to perfection. (Is that an oxymoron?)', '2007-12-23 12:40:07.000000', NULL, 1),
(4331060, 622743, 83313, '<td valign="top">A good shot, and the composition draws my eye up the hill. I just don''t personally find it wows me. Perhaps it is the slight skew to the horizon or the cut off right side of the building that wants me to look further than the image frame.</td>', 'A good shot, and the composition draws my eye up the hill. I just don''t personally find it wows me. Perhaps it is the slight skew to the horizon or the cut off right side of the building that wants me to look further than the image frame.', '2007-12-23 12:43:37.000000', NULL, 1),
(4331061, 622776, 79038, '<td valign="top">Beautiful Shot.</td>', 'Beautiful Shot.', '2007-12-23 12:44:21.000000', NULL, 1),
(4331070, 623747, 83313, '<td valign="top">Nice colors and detail here. May or may not be considered Wabi-Sabi depending on one''s definition.</td>', 'Nice colors and detail here. May or may not be considered Wabi-Sabi depending on one''s definition.', '2007-12-23 12:49:33.000000', NULL, 1),
(4331182, 623744, 77551, '<td valign="top">This is a beautiful shot. If you could just make the powerlines disappear, like they do in the movies, it would be even better.</td>', 'This is a beautiful shot. If you could just make the powerlines disappear, like they do in the movies, it would be even better.', '2007-12-23 13:56:24.000000', NULL, 1),
