(4335699, 623496, 43774, '<td valign="top">When I asked if this was the same airport I was thinking of <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=62318" rel="nofollow" target="_blank">jaysonmc</a>''s photo.</td>', 'When I asked if this was the same airport I was thinking of  jaysonmc''s photo.', '2007-12-26 08:45:25.000000', NULL, 0),
