(4341161, 623227, 71459, '<td valign="top">Oh whoa, trippy! I like it! :)</td>', 'Oh whoa, trippy! I like it! :)', '2007-12-28 13:55:41.000000', NULL, 0),
(4341208, 622625, 71459, '<td valign="top">I like this a lot! :)</td>', 'I like this a lot! :)', '2007-12-28 14:24:01.000000', NULL, 0),
(4341235, 622790, 41337, '<td valign="top">Sorry about the DQ. It''s a nice shot but I have to agree with eyewave on this. The challenge isn''t just what the title says. That''s only 50% of it. The title gives you the basic idea and the challenge description gives you the finer details. However, this isn''t like it''s the first time the description got totally ignored in a challenge so it''s probably about time we just nix that part and describe everything in the title only since that''s all people read anyway.</td>', 'Sorry about the DQ. It''s a nice shot but I have to agree with eyewave on this. The challenge isn''t just what the title says. That''s only 50% of it. The title gives you the basic idea and the challenge description gives you the finer details. However, this isn''t like it''s the first time the description got totally ignored in a challenge so it''s probably about time we just nix that part and describe everything in the title only since that''s all people read anyway.', '2007-12-28 14:32:34.000000', NULL, 0),
(4341239, 622790, 35994, '<td valign="top">Too bad on the DQ, this is a beautiful image.</td>', 'Too bad on the DQ, this is a beautiful image.', '2007-12-28 14:34:38.000000', NULL, 0),
(4341278, 623241, 53094, '<td valign="top">I like the colors and composition a lot.  You could have entered this in the Textures challenge, but certainly is beauty in the everyday.  And Silly Brad...he should know that the white stuff is foam from the surf!</td>', 'I like the colors and composition a lot.  You could have entered this in the Textures challenge, but certainly is beauty in the everyday.  And Silly Brad...he should know that the white stuff is foam from the surf!', '2007-12-28 15:02:42.000000', NULL, 0),
