INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4357009, 622918, 53548, '<td valign="top">i think the light dissapering does alot for this photo., subtle.. good</td>', 'i think the light dissapering does alot for this photo., subtle.. good', '2008-01-03 10:14:16.000000', NULL, 0),
(4357953, 622319, 11769, '<td valign="top">A lot of feeling in this one.</td>', 'A lot of feeling in this one.', '2008-01-03 15:59:27.000000', NULL, 0),
(4359881, 622319, 40797, '<td valign="top">Gorgeous Judy!!!!!</td>', 'Gorgeous Judy!!!!!', '2008-01-04 09:28:43.000000', NULL, 0),
(4373886, 623251, 66597, '<td valign="top">Colleen, I just came across this (checking out photos after return from extended trip to Montana) and think it''s superb. Really outstanding colors and composition with those drops. Will add that "Sabi" is also the root of the modern word "sabishii" which refers to loneliness. You captured the idea of fleeting beauty very well here.</td>', 'Colleen, I just came across this (checking out photos after return from extended trip to Montana) and think it''s superb. Really outstanding colors and composition with those drops. Will add that "Sabi" is also the root of the modern word "sabishii" which refers to loneliness. You captured the idea of fleeting beauty very well here.', '2008-01-08 12:07:45.000000', NULL, 0),
(4377491, 623061, 70661, '<td valign="top">This is awesome! I love these places with the white fences. The shadow really adds to the whole thing.<br/><br/><i>Message edited by author 2008-01-09 11:45:38.</i></td>', 'This is awesome! I love these places with the white fences. The shadow really adds to the whole thing.', '2008-01-09 11:44:51.000000', '2008-01-09 11:45:38.000000', 0),
(4379915, 623677, 69407, '<td valign="top">What a beautiful image and a beautiful poem - thank you ever so for sharing it... can you just imagine, you have given a gift to this poem and its writer - they have made it to the internet (which is also gifted now with this), unknown though the ending and writer may be.</td>', 'What a beautiful image and a beautiful poem - thank you ever so for sharing it... can you just imagine, you have given a gift to this poem and its writer - they have made it to the internet (which is also gifted now with this), unknown though the ending and writer may be.', '2008-01-09 23:19:51.000000', NULL, 0),
